WITH src AS (SELECT *, ROUND(unit_price / quantity, 2) AS line_total FROM order_items WHERE unit_price <= 310 AND unit_price BETWEEN 100 AND 250), order_id_summary AS (SELECT order_id, product_id, MAX(unit_price) - MIN(unit_price) AS unit_price_range, COUNT(line_total) AS line_total_count FROM src GROUP BY order_id, product_id) SELECT order_id, unit_price_range, line_total_count FROM order_id_summary ORDER BY unit_price_range DESC, line_total_count DESC;
